  <td><?= e(t(A::SALE_METHODS[$m['sale_method']])) ?></td><td><?= e($m['currency']) ?></td><td class="small"><?= (float) $m['fee_percent'] ? e(rtrim(rtrim((string) $m['fee_percent'], '0'), '.')) . ' %' : '' ?><?= (float) $m['fee_fixed'] ? ' + ' . e(money($m['fee_fixed'])) : '' ?></td>
  <td class="small"><?= $m['register_ids'] ? e(implode(', ', array_column(array_filter($registers, fn($r) => in_array((int) $r['id'], array_map('intval', explode(',', $m['register_ids'])), true)), 'name'))) : e(t('Toutes')) ?></td>
  <td><form method="post" action="<?= e(url('/pay/moyens/' . $m['id'] . '/activer')) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-outline-<?= (int) $m['active'] ? 'secondary' : 'success' ?>"><?= e(t((int) $m['active'] ? 'Désactiver' : 'Activer')) ?></button></form></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="8" class="small text-secondary"><?= e(t('Aucun moyen de paiement électronique.')) ?></td></tr><?php endif; ?></tbody></table></div></div>
