  <div class="col-md-3"><label class="form-label small mb-0"><?= e(t('Connexion (sauf TPE)')) ?></label><select name="connector_id" class="form-select form-select-sm"><option value=""></option><?php foreach ($connectors as $c): ?><option value="<?= (int) $c['id'] ?>" <?= (int) ($ed['connector_id'] ?? 0) === (int) $c['id'] ? 'selected' : '' ?>><?= e($c['name']) ?> (<?= $c['environment'] === 'prod' ? 'PROD' : 'TEST' ?>)</option><?php endforeach; ?></select></div>
  <div class="col-md-2"><label class="form-label small mb-0"><?= e(t('Enregistré comme')) ?></label><select name="sale_method" class="form-select form-select-sm"><?php foreach (A::SALE_METHODS as $k => $l): ?><option value="<?= $k ?>" <?= ($ed['sale_method'] ?? '') === $k ? 'selected' : '' ?>><?= e(t($l)) ?></option><?php endforeach; ?></select></div>
  <div class="col-md-2"><label class="form-label small mb-0"><?= e(t('Devise')) ?></label><select name="currency" class="form-select form-select-sm"><?php foreach ($currencies as $c): ?><option value="<?= e($c['code']) ?>" <?= ($ed['currency'] ?? Addons\Pay\PayEngine::shopCurrency()) === $c['code'] ? 'selected' : '' ?>><?= e($c['code']) ?></option><?php endforeach; ?></select></div>
  <div class="col-md-2"><label class="form-label small mb-0"><?= e(t('Frais %')) ?></label><input name="fee_percent" value="<?= e((string) ($ed['fee_percent'] ?? '')) ?>" class="form-control form-control-sm"></div>
  <div class="col-md-2"><label class="form-label small mb-0"><?= e(t('Frais fixes')) ?></label><input name="fee_fixed" value="<?= e((string) ($ed['fee_fixed'] ?? '')) ?>" class="form-control form-control-sm"></div>
  <div class="col-md-2"><label class="form-label small mb-0"><?= e(t('Minimum')) ?></label><input name="min_amount" value="<?= e((string) ($ed['min_amount'] ?? '')) ?>" class="form-control form-control-sm"></div>
  <div class="col-md-2"><label class="form-label small mb-0"><?= e(t('Maximum')) ?></label><input name="max_amount" value="<?= e((string) ($ed['max_amount'] ?? '')) ?>" class="form-control form-control-sm"></div>
  <div class="col-md-2"><label class="form-label small mb-0"><?= e(t('Expiration (min)')) ?></label><input type="number" name="expiry_minutes" min="1" max="1440" value="<?= (int) ($ed['expiry_minutes'] ?? 15) ?>" class="form-control form-control-sm"></div>
  <div class="col-md-6"><label class="form-label small mb-0"><?= e(t('Caisses autorisées (aucune = toutes)')) ?></label><select name="register_ids[]" multiple size="3" class="form-select form-select-sm"><?php foreach ($registers as $r): ?><option value="<?= (int) $r['id'] ?>" <?= in_array((int) $r['id'], $sel, true) ? 'selected' : '' ?>><?= e($r['name']) ?></option><?php endforeach; ?></select></div>
  <div class="col-md-2"><label class="form-label small mb-0"><?= e(t('Ordre')) ?></label><input type="number" name="sort" value="<?= (int) ($ed['sort'] ?? 0) ?>" class="form-control form-control-sm"></div>
  <div class="col-md-4 d-flex align-items-end"><button class="btn btn-sm btn-primary"><?= e(t('Enregistrer')) ?></button><?php if ($ed): ?> <a class="btn btn-sm btn-outline-secondary ms-2" href="<?= e(url('/pay/moyens')) ?>"><?= e(t('Annuler')) ?></a><?php endif; ?></div>
  <div class="col-12 form-text"><?= e(t('Les frais saisis ici servent d\'estimation ; les rapports utilisent les frais réellement communiqués par le prestataire quand il les renvoie.')) ?></div>
